/*
  MELATO HEADER / FOOTER EMERGENCY FIX
    Removes visible stray bracket text nodes, restores missing cart/search icons,
      and prevents broken search modal behavior.
      */

      (function () {
        function removeStrayBracketText() {
            var walker = document.createTreeWalker(
                  document.body,
                        NodeFilter.SHOW_TEXT,
                              {
                                      acceptNode: function (node) {
                                                var parent = node.parentElement;
                                                          if (!parent) return NodeFilter.FILTER_REJECT;

                                                                    var tag = parent.tagName ? parent.tagName.toLowerCase() : '';
                                                                              if (tag === 'script' || tag === 'style' || tag === 'textarea') {
                                                                                          return NodeFilter.FILTER_REJECT;
                                                                                                    }

                                                                                                              var text = node.nodeValue || '';
                                                                                                                        var trimmed = text.trim();

                                                                                                                                  /*
                                                                                                                                              Only remove isolated junk like:
                                                                                                                                                          }}
                                                                                                                                                                      }}" 
                                                                                                                                                                                  }}"}}">
                                                                                                                                                                                              Never remove real content.
                                                                                                                                                                                                        */
                                                                                                                                                                                                                  if (
                                                                                                                                                                                                                              trimmed &&
                                                                                                                                                                                                                                          trimmed.length <= 12 &&
                                                                                                                                                                                                                                                      /^[}\]"'<>\/\s;]+$/.test(trimmed) &&
                                                                                                                                                                                                                                                                  trimmed.indexOf('}') !== -1
                                                                                                                                                                                                                                                                            ) {
                                                                                                                                                                                                                                                                                        return NodeFilter.FILTER_ACCEPT;
                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                            return NodeFilter.FILTER_REJECT;
                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                  var nodes = [];
                                                                                                                                                                                                                                                                                                                                      while (walker.nextNode()) {
                                                                                                                                                                                                                                                                                                                                            nodes.push(walker.currentNode);
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                    nodes.forEach(function (node) {
                                                                                                                                                                                                                                                                                                                                                          node.parentNode.removeChild(node);
                                                                                                                                                                                                                                                                                                                                                              });
                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                  function restoreCartIcon() {
                                                                                                                                                                                                                                                                                                                                                                      var headerIcons =
                                                                                                                                                                                                                                                                                                                                                                            document.querySelector('.header__icons') ||
                                                                                                                                                                                                                                                                                                                                                                                  document.querySelector('.site-header__icons') ||
                                                                                                                                                                                                                                                                                                                                                                                        document.querySelector('.melato-header__icons') ||
                                                                                                                                                                                                                                                                                                                                                                                              document.querySelector('header');

                                                                                                                                                                                                                                                                                                                                                                                                  if (!headerIcons) return;

                                                                                                                                                                                                                                                                                                                                                                                                      var cartLink =
                                                                                                                                                                                                                                                                                                                                                                                                            document.querySelector('.header__icon--cart') ||
                                                                                                                                                                                                                                                                                                                                                                                                                  document.querySelector('a[href="/cart"]') ||
                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelector('a[href*="/cart"]');

                                                                                                                                                                                                                                                                                                                                                                                                                            if (!cartLink) {
                                                                                                                                                                                                                                                                                                                                                                                                                                  cartLink = document.createElement('a');
                                                                                                                                                                                                                                                                                                                                                                                                                                        cartLink.href = '/cart';
                                                                                                                                                                                                                                                                                                                                                                                                                                              cartLink.className = 'header__icon header__icon--cart melato-restored-cart';
                                                                                                                                                                                                                                                                                                                                                                                                                                                    cartLink.setAttribute('aria-label', 'Cart');
                                                                                                                                                                                                                                                                                                                                                                                                                                                          headerIcons.appendChild(cartLink);
                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                  var hasIcon = cartLink.querySelector('svg');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!hasIcon) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cartLink.innerHTML =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<svg aria-hidden="true" viewBox="0 0 24 24" fill="none">' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '<path d="M6.5 8.5h11l-.8 10.2a2 2 0 0 1-2 1.8H9.3a2 2 0 0 1-2-1.8L6.5 8.5Z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<path d="M9 8.5V7a3 3 0 0 1 6 0v1.5" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            '</svg>' +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    '<span class="visually-hidden">Cart</span>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            cartLink.style.display = 'inline-flex';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cartLink.style.opacity = '1';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cartLink.style.visibility = 'visible';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function fixSearchLinks() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var searchLinks = document.querySelectorAll(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '.header__icon--search, a[href="/search"], a[href*="/search"]'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          searchLinks.forEach(function (link) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!link) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              If the search modal is causing a Liquid error, force the icon
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      to go to the clean /search page instead.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  link.setAttribute('href', '/search');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        link.removeAttribute('aria-controls');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              link.removeAttribute('data-modal-opener');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    link.removeAttribute('data-drawer-open');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          link.removeAttribute('data-search-open');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                link.addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'click',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function (event) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          var href = link.getAttribute('href');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (href === '/search') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function fixDuplicateMenuIcons() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var menuButtons = document.querySelectorAll(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  '.header__icon--menu, summary.header__icon--menu'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          menuButtons.forEach(function (button) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                var svgs = button.querySelectorAll('svg');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (svgs.length > 1) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              for (var i = 1; i < svgs.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        svgs[i].style.display = 'none';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            var closeIcons = button.querySelectorAll('.icon-close');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  closeIcons.forEach(function (icon) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          icon.style.display = 'none';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function runFixes() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            removeStrayBracketText();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                restoreCartIcon();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fixSearchLinks();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fixDuplicateMenuIcons();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (document.readyState === 'loading') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.addEventListener('DOMContentLoaded', runFixes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      runFixes();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          document.addEventListener('shopify:section:load', runFixes);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          })();